import { cn } from "@/lib/utils"
import { Spinner } from "@/components/ui/spinner"

/**
 * One chip per source the AI checked, numbered in the order it checked them.
 * The same number marks the spot on the drawing and heads the evidence card.
 */
export interface EvidenceChipProps {
  n: number
  label: string
  /** checking: being read · landed: done · stale: older than 15 min */
  status?: "checking" | "landed" | "stale"
  /** Its card is open below. */
  selected?: boolean
  /** Its card or drawing mark is hovered elsewhere. */
  linked?: boolean
  age?: string
  className?: string
}

export function EvidenceChip({ n, label, status = "landed", selected = false, linked = false, age = "15 min", className }: EvidenceChipProps) {
  return (
    <span
      data-slot="evidence-chip"
      data-status={status}
      aria-busy={status === "checking" || undefined}
      className={cn(
        "inline-flex h-7 items-center gap-1.5 bg-raised pr-2 pl-[5px] text-[13px] transition-[box-shadow,background-color] duration-200 hover:shadow-[0_0_0_1.5px_var(--gc-accent)]",
        linked && "shadow-[0_0_0_1.5px_var(--gc-accent)]",
        selected && "bg-foreground text-background",
        status === "checking" && "text-muted-foreground",
        status === "stale" && "opacity-60",
        className
      )}
    >
      {status === "checking" ? (
        <Spinner className="mx-0.5" />
      ) : (
        <span className={cn("grid size-4 place-items-center font-mono text-[10px]", selected ? "bg-background text-foreground" : "bg-[var(--gc-badge-bg)] text-on-signal")}>{n}</span>
      )}
      {label}
      {status === "stale" && <span className="ml-1 font-mono text-xs text-muted-foreground">{age}</span>}
    </span>
  )
}
